import{_ as t,o as r,c as n,a2 as e}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"设置说明","description":"","frontmatter":{},"headers":[],"relativePath":"zh/settings.md","filePath":"zh/settings.md","lastUpdated":null}'),s={name:"zh/settings.md"};function l(a,o,i,g,d,h){return r(),n("div",null,[...o[0]||(o[0]=[e('<h1 id="设置说明" tabindex="-1">设置说明 <a class="header-anchor" href="#设置说明" aria-label="Permalink to &quot;设置说明&quot;">​</a></h1><p>在 <strong>设置</strong> 页通过左侧分组调整：常规、外观、网络、内核、关于。</p><h2 id="常规-general" tabindex="-1">常规（General） <a class="header-anchor" href="#常规-general" aria-label="Permalink to &quot;常规（General）&quot;">​</a></h2><ul><li><strong>工作目录</strong>：dsh 启动所在目录；留空用配置目录下的 <code>workspace</code>。</li><li><strong>端口</strong>：自动（推荐，从 3080 起挑空闲端口）或手动指定。</li><li><strong>关闭按钮行为</strong>：隐藏到托盘或直接退出；可选择「每次询问」或「记住选择」。</li></ul><h3 id="新标签页与搜索" tabindex="-1">新标签页与搜索 <a class="header-anchor" href="#新标签页与搜索" aria-label="Permalink to &quot;新标签页与搜索&quot;">​</a></h3><ul><li><strong>默认搜索引擎</strong>：地址栏输入非网址内容、以及内置导航页搜索时使用的引擎（百度 / 搜狗 / 360 / Bing / Google / DuckDuckGo）。</li><li><strong>新标签页</strong>：点标签条「＋」时打开什么——<strong>内置导航页</strong>（带搜索框与常用站点）或<strong>自定义网址</strong>（填写固定 URL）。</li><li><strong>常用站点快捷方式</strong>：名称 + 网址的列表，显示在内置导航页上，点击直达。</li></ul><h3 id="其它" tabindex="-1">其它 <a class="header-anchor" href="#其它" aria-label="Permalink to &quot;其它&quot;">​</a></h3><ul><li><strong>恢复默认设置</strong>：一键重置并重启 dsh。</li></ul><h2 id="外观-appearance" tabindex="-1">外观（Appearance） <a class="header-anchor" href="#外观-appearance" aria-label="Permalink to &quot;外观（Appearance）&quot;">​</a></h2><ul><li><strong>主题</strong>：跟随系统 / 浅色 / 深色，切换即时生效。</li><li><strong>语言（二级下拉）</strong>：选择 中文 / English，并选择扩展翻译（zh：简体/二次元/文言/繁体中文；en：English/海盗腔/莎翁腔）。扩展翻译为<strong>文本覆盖</strong>，仅当前语言生效，不改 dsh 设置。</li><li><strong>界面缩放</strong>：50%~200%（作用于外壳窗口与内嵌 webview）。</li><li><strong>禁用系统缩放</strong>：开启会提示重启生效（忽略操作系统显示缩放）。</li></ul><h2 id="网络-network" tabindex="-1">网络（Network） <a class="header-anchor" href="#网络-network" aria-label="Permalink to &quot;网络（Network）&quot;">​</a></h2><ul><li><strong>npm 镜像源</strong>：官方 registry / npmmirror。</li><li><strong>代理</strong>：启用 + 协议(HTTP/SOCKS5) + 主机 + 端口 + <strong>代理范围</strong>（npm 安装/下载、Node 下载部署、内核更新检查）。当前 npm 范围实际走代理；Node 下载与更新检查的代理支持为后续项。</li></ul><h2 id="内核-kernel" tabindex="-1">内核（Kernel） <a class="header-anchor" href="#内核-kernel" aria-label="Permalink to &quot;内核（Kernel）&quot;">​</a></h2><ul><li><strong>启动 / 停止 / 重启</strong>：直接控制 dsh；状态标签实时显示。</li><li><strong>立即应用</strong>：运行类配置改动后点此保存并重启 dsh。</li><li><strong>内核来源</strong>：内置（装到应用目录、用内置 Node）或 全局。</li><li><strong>Node 运行时</strong>：Electron 自带 / 系统（≥20）/ 本地部署；<strong>npm 来源</strong>：系统 / 内置（下载）/ 本地 Node 自带。</li><li><strong>启动器路径</strong>：仅在「全局」模式显示，用文件选择器选取。</li><li><strong>内核更新</strong>：启动时检查、包含测试版；手动「检查 / 更新内核」。</li><li><strong>选择版本 / 卸载</strong>：浏览并<strong>安装 / 切换</strong>到任意历史版本；<strong>卸载</strong>会先自动停止 dsh，卸载后显示安装引导。</li></ul><div class="warning custom-block"><p class="custom-block-title">升级 / 切换 / 卸载时</p><p>这些操作会<strong>先强制停止所有运行中的 dsh 实例</strong>（正在运行会先弹确认）。成功后会自动重启 dsh 以运行新版本；失败会检测占用原因并给出提示。</p></div><h2 id="关于-about" tabindex="-1">关于（About） <a class="header-anchor" href="#关于-about" aria-label="Permalink to &quot;关于（About）&quot;">​</a></h2><ul><li>显示应用版本与运行架构。</li><li><strong>自动更新</strong>：启动时检查应用新版本并后台下载；<strong>检测测试版</strong>、<strong>开发模式</strong>（F12 开关 DevTools）。</li></ul><blockquote><p>设置卡片均可点标题折叠。主题与语言的基础来源仍是 dsh 的 <code>~/.dsh/settings.yaml</code>；应用自身设置（常规/网络/内核/关于等）存于<strong>应用配置目录</strong> <code>settings.json</code>（默认 <code>~/.config/dsh_shell</code>，开发态 <code>dsh_shell_dev</code>，可在向导/设置中选择配置目录并迁移）。</p></blockquote>',18)])])}const p=t(s,[["render",l]]);export{u as __pageData,p as default};
